contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run drives c.transfer with arbitrary inputs and asserts the general property
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        // precondition: require a non-empty _tos to satisfy C.transfer's require and allow the call to proceed
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // call C.transfer and capture whether it reverted and the returned value
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if transfer did not revert then it must have returned true.
        // We express this as: not reverted implies ret == true
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

